-- ISSUE-008: read-only classroom join/reference code.
-- Generated by the database on insert (unambiguous alphabet, no 0/O/1/I) and immutable afterwards.
CREATE OR REPLACE FUNCTION public.fn_generate_classroom_code()
RETURNS text
LANGUAGE plpgsql
VOLATILE
SET search_path = pg_catalog
AS $$
DECLARE
  alphabet constant text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  result text := '';
  i integer;
BEGIN
  FOR i IN 1..6 LOOP
    result := result || pg_catalog.substr(
      alphabet,
      1 + pg_catalog.floor(pg_catalog.random() * pg_catalog.length(alphabet))::integer,
      1
    );
  END LOOP;
  RETURN result;
END;
$$;

ALTER TABLE public.classrooms
  ADD COLUMN code text NOT NULL DEFAULT public.fn_generate_classroom_code();

ALTER TABLE public.classrooms
  ADD CONSTRAINT uq_classrooms_code UNIQUE (code),
  ADD CONSTRAINT chk_classrooms_code_format CHECK (code ~ '^[A-Z2-9]{6}$');

CREATE OR REPLACE FUNCTION public.fn_classrooms_code_immutable()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = pg_catalog
AS $$
BEGIN
  IF NEW.code IS DISTINCT FROM OLD.code THEN
    RAISE EXCEPTION 'CLASSROOM_CODE_READ_ONLY' USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER trg_classrooms_code_immutable
BEFORE UPDATE ON public.classrooms
FOR EACH ROW
EXECUTE FUNCTION public.fn_classrooms_code_immutable();
